const selectSupplier=id=>{const s=suppliers.find(x=>x.id===id);if(s)setForm(f=>({...f,supplier_id:id,fournisseur:{nom:s.nom,ice:s.ice||'',adresse:s.adresse||'',ville:s.ville||'',tel:s.tel||'',email:s.email||''}}));};const selectDA=daId=>{const da=daApprouvees.find(d=>d.id===daId);if(!da){setForm(f=>({...f,purchase_request_id:''}));return;}const mappedItems=(da.items||[]).map(it=>({article:it.article||'',categorie:it.categorie||'engrais',quantite:String(it.quantite||''),unite:it.unite||'kg',prix_unitaire:'',taux_tva:20}));setForm(f=>({...f,purchase_request_id:daId,items:mappedItems.length?mappedItems:[{...emptyItem}]}));};const updateItem=(idx,field,value)=>{setForm(f=>{const items=[...f.items];items[idx]={...items[idx],[field]:value};return{...f,items};});};const addItem=()=>setForm(f=>({...f,items:[...f.items,{...emptyItem}]}));const removeItem=idx=>{setForm(f=>f.items.length>1?{...f,items:f.items.filter((_,i)=>i!==idx)}:f);};const calcTotal=()=>{let ht=0,tva=0;form.items.forEach(it=>{const mht=(parseFloat(it.quantite)||0)*(parseFloat(it.prix_unitaire)||0);ht+=mht;tva+=mht*(it.taux_tva!=null&&it.taux_tva!==''?parseFloat(it.taux_tva):20)/100;});return{ht:Math.round(ht*100)/100,tva:Math.round(tva*100)/100,ttc:Math.round((ht+tva)*100)/100};};const handleCreate=()=>{if(!form.fournisseur.nom){alert('Sélectionnez un fournisseur');return;}if(!form.items.some(i=>i.article&&i.quantite&&i.prix_unitaire)){alert('Ajoutez au moins un article complet');return;}const validItems=form.items.filter(i=>i.article&&i.quantite&&i.prix_unitaire);fetch('/api/stock?action=create-bdc',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...form,items:validItems,created_by:{profileId:currentProfile,name:profileData?.name||currentProfile}})}).then(r=>r.json()).then(json=>{if(json.success){setJustCreated({id:json.id,numero:json.numero});loadBdc();}else alert('Erreur: '+(json.error||'Echec'));}).catch(()=>alert('Erreur réseau'));};// Génère le PDF du BDC et l'upload v